void driverName() {
    
    Brain.Screen.setFillColor(transparent);
    Brain.Screen.setPenColor(white);
    Brain.Screen.setFont(mono30);
    Brain.Screen.setCursor(1, 12);
    
    if(driver == 0) {
        Brain.Screen.print("Driver: None");
    } else if(driver == 1) {
        Brain.Screen.print("Driver: Alivia");
    } else if(driver == 2) {
        Brain.Screen.print("Driver: Andrew");
    } else if(driver == 3) {
        Brain.Screen.print("Driver: Ayan");
    } else if(driver == 4) {
        Brain.Screen.print("Driver: Bennett");
    } else if(driver == 5) {
        Brain.Screen.print("Driver: Brian");
    } else if(driver == 6) {
        Brain.Screen.print("Driver: Connor");
    } else if(driver == 7) {
        Brain.Screen.print("Driver: Grace");
    } else if(driver == 8) {
        Brain.Screen.print("Driver: Maria");
    }
    
}

