void driveMode() {
    
    if(drawBackground==true){
        background();
        drawBackground=false;
    }

    driverName();

    //Battery code
    int batteryLevel = Brain.Battery.capacity();

    Brain.Screen.drawRectangle(75, 95, 20, 79, white);

    //above 90%
    if (batteryLevel > 90) {
        Brain.Screen.drawRectangle(100, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(100, 55, 20, 159, black);
    }

    //above 80%
    if (batteryLevel > 80) {
        Brain.Screen.drawRectangle(125, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(125, 55, 20, 159, black);
    }

    //above 70%
    if (batteryLevel > 70) {
        Brain.Screen.drawRectangle(150, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(150, 55, 20, 159, black);
    }

    //above 60%
    if (batteryLevel > 60) {
        Brain.Screen.drawRectangle(175, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(175, 55, 20, 159, black);
    }

    //above 50%
    if (batteryLevel > 50) {
        Brain.Screen.drawRectangle(200, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(200, 55, 20, 159, black);
    }

    //above 40%
    if (batteryLevel > 40) {
        Brain.Screen.drawRectangle(225, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(225, 55, 20, 159, black);
    }

    //above 30%
    if (batteryLevel > 30) {
        Brain.Screen.drawRectangle(250, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(250, 55, 20, 159, black);
    }

    //above 20%
    if (batteryLevel > 20) {
        Brain.Screen.drawRectangle(275, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(275, 55, 20, 159, black);
    }

    //above 10%
    if (batteryLevel > 10) {
        Brain.Screen.drawRectangle(300, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(300, 55, 20, 159, black);
    }

    //above 1%
    if (batteryLevel > 1) {
        Brain.Screen.drawRectangle(325, 55, 20, 159, yellow);
    } else {
        Brain.Screen.drawRectangle(325, 55, 20, 159, black);
    }
    
    backButton();

    check();

    if (Brain.Screen.pressing() && 434 <= Brain.Screen.xPosition() && Brain.Screen.xPosition() <= 474 && 60 <= Brain.Screen.yPosition() && Brain.Screen.yPosition() <= 190) {
        
        backButtonPressed();

        wait(0.5, sec);

    }

    if (Brain.Screen.pressing() && 25 <= Brain.Screen.xPosition() && Brain.Screen.xPosition() <= 65 && 114 <= Brain.Screen.yPosition() && Brain.Screen.yPosition() <= 154) {
        
        checkPressed();

        wait(0.5, sec);

    }

}

